"""DOM node definitions (no HTML libraries)."""

from __future__ import annotations

from dataclasses import dataclass, field


@dataclass(slots=True)
class TextNode:
    """A run of character data (already trimmed by the parser)."""

    text: str


@dataclass(slots=True)
class ElementNode:
    """An element node.

    Nodes only ever reference their children, never their parent, so the
    structure is a tree and cannot contain cycles.
    """

    tag: str
    attributes: list[tuple[str, str]] = field(default_factory=list)
    children: list[ElementNode | TextNode] = field(default_factory=list)


@dataclass(slots=True)
class DocumentNode:
    """The document root ('.'), holding the top-level elements."""

    children: list[ElementNode] = field(default_factory=list)

"""CLI entry point for dom-parser-python (Section 5)."""

from __future__ import annotations

import sys
from enum import StrEnum
from pathlib import Path
from typing import NamedTuple

from tokenizer import Token, tokenize

USAGE: str = (
    "Usage: domparser FILE [--tree | --text | --find-tag TAG | "
    "--find-id ID | --find-class CLASS]"
)


class Mode(StrEnum):
    """Output mode selected on the command line."""

    TREE = "--tree"
    TEXT = "--text"
    FIND_TAG = "--find-tag"
    FIND_ID = "--find-id"
    FIND_CLASS = "--find-class"


_VALUE_MODES: frozenset[Mode] = frozenset(
    {Mode.FIND_TAG, Mode.FIND_ID, Mode.FIND_CLASS}
)
_PLAIN_MODES: frozenset[Mode] = frozenset({Mode.TREE, Mode.TEXT})


class ParsedArgs(NamedTuple):
    """Validated command-line arguments."""

    path: str
    mode: Mode | None
    value: str | None


def _mode_from(token: str) -> Mode | None:
    """Return the Mode for a flag token, or None if it is not a known flag."""
    try:
        return Mode(token)
    except ValueError:
        return None


def _parse_args(args: list[str]) -> ParsedArgs | None:
    """Validate CLI arguments.

    Args:
        args: Argument list excluding the program name.

    Returns:
        The parsed arguments, or None if the arguments are missing/invalid.
    """
    if not args or args[0].startswith("-"):
        return None
    path = args[0]
    rest = args[1:]
    if not rest:
        return ParsedArgs(path, None, None)
    if len(rest) == 1:
        mode = _mode_from(rest[0])
        if mode is None or mode not in _PLAIN_MODES:
            return None
        return ParsedArgs(path, mode, None)
    if len(rest) == 2:
        mode = _mode_from(rest[0])
        if mode is None or mode not in _VALUE_MODES:
            return None
        value = rest[1]
        if value.startswith("-"):
            return None
        return ParsedArgs(path, mode, value)
    return None


def _read_file(path: str) -> str | None:
    """Read a text file.

    Args:
        path: Path of the file to read.

    Returns:
        The file content, or None if the file cannot be opened.
    """
    try:
        return Path(path).read_text(encoding="utf-8")
    except (FileNotFoundError, PermissionError):
        return None


def main(argv: list[str] | None = None) -> int:
    """Run the domparser CLI.

    Args:
        argv: Argument list excluding the program name. Defaults to sys.argv[1:].

    Returns:
        Process exit code (0 on success, 1 on usage or I/O errors).
    """
    args: list[str] = sys.argv[1:] if argv is None else argv
    parsed: ParsedArgs | None = _parse_args(args)
    if parsed is None:
        print(USAGE, file=sys.stderr)
        return 1
    content: str | None = _read_file(parsed.path)
    if content is None:
        print(f"Cannot open file: {parsed.path}", file=sys.stderr)
        return 1
    # Temporary: dump the token stream (parser not implemented yet).
    tokens: list[Token] = tokenize(content)
    for token in tokens:
        print(f"{token.kind}: {token.raw!r}")
    return 0


if __name__ == "__main__":
    raise SystemExit(main())

"""Tests for the handwritten tokenizer."""

from __future__ import annotations

from tokenizer import Token, TokenKind, tokenize


def test_prompt_example() -> None:
    assert tokenize("<div><p>Hi</p></div>") == [
        Token(TokenKind.OPEN_TAG, "<div>"),
        Token(TokenKind.OPEN_TAG, "<p>"),
        Token(TokenKind.TEXT, "Hi"),
        Token(TokenKind.CLOSE_TAG, "</p>"),
        Token(TokenKind.CLOSE_TAG, "</div>"),
    ]


def test_empty_input() -> None:
    assert tokenize("") == []


def test_text_only() -> None:
    assert tokenize("Hi") == [Token(TokenKind.TEXT, "Hi")]


def test_whitespace_and_newlines_are_preserved() -> None:
    assert tokenize("<a>\n  x\n</a>") == [
        Token(TokenKind.OPEN_TAG, "<a>"),
        Token(TokenKind.TEXT, "\n  x\n"),
        Token(TokenKind.CLOSE_TAG, "</a>"),
    ]


def test_adjacent_tags_produce_no_text_token() -> None:
    assert tokenize("<p></p>") == [
        Token(TokenKind.OPEN_TAG, "<p>"),
        Token(TokenKind.CLOSE_TAG, "</p>"),
    ]


def test_close_tag_detection() -> None:
    assert tokenize("</p>")[0].kind is TokenKind.CLOSE_TAG


def test_open_tag_detection() -> None:
    assert tokenize("<p>")[0].kind is TokenKind.OPEN_TAG


def test_unterminated_tag_is_text() -> None:
    assert tokenize("<div") == [Token(TokenKind.TEXT, "<div")]


def test_raw_is_verbatim_source_slice() -> None:
    tokens: list[Token] = tokenize("  <img src='x'>  ")
    assert tokens[0] == Token(TokenKind.TEXT, "  ")
    assert tokens[1] == Token(TokenKind.OPEN_TAG, "<img src='x'>")
    assert tokens[2] == Token(TokenKind.TEXT, "  ")

"""Tests for the DOM builder."""

from __future__ import annotations

from dom import DocumentNode, ElementNode, TextNode
from parser import build_dom
from tokenizer import Token, TokenKind, tokenize


def test_prompt_example() -> None:
    document: DocumentNode = build_dom(tokenize("<div><p>Hi</p></div>"))
    assert document == DocumentNode(
        children=[
            ElementNode(
                tag="div",
                children=[ElementNode(tag="p", children=[TextNode(text="Hi")])],
            )
        ]
    )


def test_empty_input_yields_empty_document() -> None:
    assert build_dom([]) == DocumentNode()


def test_whitespace_only_text_is_dropped() -> None:
    document: DocumentNode = build_dom(tokenize("<div>\n   \n</div>"))
    assert document == DocumentNode(
        children=[ElementNode(tag="div", attributes=[], children=[])]
    )


def test_text_is_trimmed() -> None:
    document: DocumentNode = build_dom(tokenize("<p>  Hi there  </p>"))
    assert document.children[0].children == [TextNode(text="Hi there")]


def test_attributes_are_ignored_for_now() -> None:
    document: DocumentNode = build_dom(tokenize('<div class="hero" id="main">Hi</div>'))
    element: ElementNode = document.children[0]
    assert element.tag == "div"
    assert element.attributes == []
    assert element.children == [TextNode(text="Hi")]


def test_text_before_root_element_is_dropped() -> None:
    assert build_dom(tokenize("just text")) == DocumentNode()


def test_multiple_root_elements() -> None:
    document: DocumentNode = build_dom(tokenize("<a>1</a><b>2</b>"))
    assert [element.tag for element in document.children] == ["a", "b"]


def test_nested_elements() -> None:
    document: DocumentNode = build_dom(tokenize("<a><b><c>x</c></b></a>"))
    a: ElementNode = document.children[0]
    child_of_a = a.children[0]
    assert isinstance(child_of_a, ElementNode)
    child_of_b = child_of_a.children[0]
    assert isinstance(child_of_b, ElementNode)
    assert [a.tag, child_of_a.tag, child_of_b.tag] == ["a", "b", "c"]


def test_unclosed_elements_stay_in_tree() -> None:
    document: DocumentNode = build_dom(tokenize("<div><p>Hi"))
    assert document == DocumentNode(
        children=[
            ElementNode(
                tag="div",
                children=[ElementNode(tag="p", children=[TextNode(text="Hi")])],
            )
        ]
    )


def test_close_tag_without_open_is_ignored() -> None:
    assert build_dom([Token(TokenKind.CLOSE_TAG, "</div>")]) == DocumentNode()


def test_mismatched_close_tag_pops_stack() -> None:
    document: DocumentNode = build_dom(tokenize("<a><b></a>"))
    assert [element.tag for element in document.children] == ["a"]

